def compute(vars):
    beginning = vars["v1"]
    ending = vars["v2"]
    net_change = ending - beginning
    return {
        "value": net_change,
        "trace": {
            "beginning": beginning,
            "ending": ending,
            "net_change": net_change,
            "output_meta": {
                "currency": None,
                "scale": "thousand",
                "unit": "shares"
            }
        }
    }
